/**
 * Generate `#pantry/test/reading-slugs.generated.ts` from `docs/spec-readings.md`: every reading's
 * slug, in the register's order, and their union, `ReadingSlug`, so the census's map of readings,
 * keyed by that union, fails to typecheck until each reading the register adds has its entry.
 *
 * Run it as `pnpm --filter @qti-pie/pantry run generate:reading-slugs`; the queue runs it on every
 * merged tree (QP-GATE's regeneration), so the generated file is never text-merged.
 */
import * as NodeRuntime from "@effect/platform-node/NodeRuntime";
import * as NodeServices from "@effect/platform-node/NodeServices";
import path from "node:path";
import { Effect, FileSystem } from "effect";
import { registerOf } from "#pantry/test/live-readings.ts";

/**
 * The register, at the repository's root.
 */
const registerPath = path.resolve(
  import.meta.dirname,
  "..",
  "..",
  "..",
  "..",
  "docs",
  "spec-readings.md",
);

/**
 * The generated module.
 */
const generatedPath = path.resolve(import.meta.dirname, "reading-slugs.generated.ts");

/**
 * The generated module's text.
 *
 * @param slugs - Every reading's slug, in the register's order.
 * @returns The module.
 */
const moduleOf = (slugs: readonly string[]): string =>
  [
    "/**",
    " * Every spec reading's slug, in `docs/spec-readings.md`'s order. Generated by",
    " * `generate:reading-slugs` (`#pantry/test/generate-reading-slugs.ts`); never edit it by hand.",
    " */",
    "export const readingSlugs = [",
    ...slugs.map((slug) => `  ${JSON.stringify(slug)},`),
    "] as const;",
    "",
    "/**",
    " * A spec reading's slug.",
    " */",
    "export type ReadingSlug = (typeof readingSlugs)[number];",
    "",
  ].join("\n");

const program = Effect.gen(function* generate() {
  const fs = yield* FileSystem.FileSystem;
  const register = registerOf(yield* fs.readFileString(registerPath));
  if (register.malformed.length > 0) {
    return yield* Effect.fail(
      new Error(
        `docs/spec-readings.md holds list items that are no reading: ${register.malformed.join("; ")}`,
      ),
    );
  }

  yield* fs.writeFileString(generatedPath, moduleOf(register.readings.map(({ slug }) => slug)));
});

NodeRuntime.runMain(program.pipe(Effect.provide(NodeServices.layer)));
